<?php require_once 'db.php'; require_login(); csrf_check(); $page_title='Reserve'; $s=db()->prepare("SELECT id, flight_code AS name, CONCAT(origin,' → ',destination,' · ',flight_date,' · ',cabin_class) AS detail, fare AS price, seats_available AS stock FROM flights WHERE id=?");$s->execute([(int)($_GET['id']??$_POST['id']??0)]);$item=$s->fetch();if(!$item){flash('Item not found.');go('search.php');}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if((int)$item['stock']<1){$err='No availability remaining for this item.';}else{try{$detail=trim($_POST['passenger']).' · '.$_POST['seat'].' seat · '.$_POST['contact'];$amount=(float)$item['price'];$s=db()->prepare("INSERT INTO bookings(user_id,item_id,item_name,details,amount,status) VALUES(?,?,?,?,?,?)");$s->execute([$_SESSION['user_id'],$item['id'],$item['name'],$detail,$amount,'Confirmed']);$u=db()->prepare("UPDATE flights SET seats_available=seats_available-1 WHERE id=? AND seats_available>0");$u->execute([$item['id']]);flash('Flight ticket reserved. Payment is simulated for this lab.');go('payment.php?id='.db()->lastInsertId());}catch(Throwable $e){$err='Could not save your reservation. Please retry.';}}} include 'header.php'; ?>
<section class="section" style="max-width:760px;margin:auto"><div class="eyebrow">STEP 1 · DETAILS</div><h1 style="font-size:3rem">Complete your selection.</h1><?php if($err): ?><div class="notice"><?= h($err) ?></div><?php endif; ?><div class="panel"><h2><?= h($item['name']) ?></h2><p class="muted"><?= h($item['detail']) ?></p><div class="price">₹<?= number_format($item['price'],0) ?></div><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><div class="field"><label>Passenger name</label><input name="passenger" required></div><div class="field"><label>Seat preference</label><select name="seat"><option>Window</option><option>Aisle</option><option>Middle</option></select></div><div class="field"><label>Contact email</label><input type="email" name="contact" required></div><button class="btn">Confirm details</button></form></div></section><?php include 'footer.php'; ?>